package com.sugr.bridge;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Minimal hand-written JSON value model: parse, build, and encode - no
 * Jackson databind, per plan.md. Used both by hand-written binds (via the
 * {@link #quote} / {@link #parseStringArray} convenience methods) and by
 * code generated by the {@code processor} module (records, List/Map, numbers).
 */
public sealed interface Json {

    record Str(String value) implements Json {
    }

    record Num(double value) implements Json {
    }

    record Bool(boolean value) implements Json {
    }

    record Null() implements Json {
    }

    record Arr(List<Json> items) implements Json {
    }

    record Obj(Map<String, Json> fields) implements Json {
    }

    Json NULL = new Null();

    static Json of(String s) {
        return s == null ? NULL : new Str(s);
    }

    static Json of(double d) {
        return new Num(d);
    }

    static Json of(long l) {
        return new Num(l);
    }

    static Json of(boolean b) {
        return new Bool(b);
    }

    static Json array(List<Json> items) {
        return new Arr(items);
    }

    static Json object(Map<String, Json> fields) {
        return new Obj(fields);
    }

    /**
     * Default limit for how deeply arrays/objects may nest in {@link #parse(String)}.
     * The parser is recursive, so without a cap a hostile page could send
     * {@code [[[[...]]]]} thousands of levels deep and blow the stack - a
     * {@code StackOverflowError} inside an FFM upcall takes the whole JVM down.
     * 64 is far beyond anything a real bridge payload needs.
     */
    int DEFAULT_MAX_DEPTH = 64;

    /** Parses a single JSON value; throws {@link JsonException} on any malformed input. */
    static Json parse(String text) {
        return parse(text, DEFAULT_MAX_DEPTH);
    }

    /** Like {@link #parse(String)}, with a custom nesting limit (arrays/objects nested more than {@code maxDepth} deep are rejected). */
    static Json parse(String text, int maxDepth) {
        if (text == null) {
            throw new JsonException("Cannot parse null as JSON");
        }
        Parser p = new Parser(text, maxDepth);
        Json value = p.parseValue();
        p.skipWs();
        if (!p.atEnd()) {
            throw new JsonException("Trailing content in JSON at " + p.pos);
        }
        return value;
    }

    /** Shorthand for {@code Json.of(s).encode()} - a JSON string literal, e.g. "hi" -> "\"hi\"". */
    static String quote(String s) {
        return of(s).encode();
    }

    /**
     * Parses a JSON array containing only strings (or null), e.g. ["a","b"] or [].
     * Throws {@link JsonException} if the text isn't valid JSON, isn't an array, or
     * holds anything other than strings/nulls.
     */
    static List<String> parseStringArray(String text) {
        Json parsed = parse(text);
        if (!(parsed instanceof Arr arr)) {
            throw new JsonException("Expected a JSON array of strings, got: " + parsed.encode());
        }
        List<String> out = new ArrayList<>(arr.items().size());
        for (Json item : arr.items()) {
            if (item.isNull()) {
                out.add(null);
            } else if (item instanceof Str s) {
                out.add(s.value());
            } else {
                throw new JsonException("Expected only strings in the JSON array, got: " + item.encode());
            }
        }
        return out;
    }

    default String asString() {
        if (this instanceof Str s) {
            return s.value();
        }
        throw new IllegalStateException("Not a JSON string: " + encode());
    }

    default double asNumber() {
        if (this instanceof Num n) {
            return n.value();
        }
        throw new IllegalStateException("Not a JSON number: " + encode());
    }

    default boolean asBoolean() {
        if (this instanceof Bool b) {
            return b.value();
        }
        throw new IllegalStateException("Not a JSON boolean: " + encode());
    }

    default boolean isNull() {
        return this instanceof Null;
    }

    default List<Json> asArray() {
        if (this instanceof Arr a) {
            return a.items();
        }
        throw new IllegalStateException("Not a JSON array: " + encode());
    }

    default Map<String, Json> asObject() {
        if (this instanceof Obj o) {
            return o.fields();
        }
        throw new IllegalStateException("Not a JSON object: " + encode());
    }

    default String encode() {
        StringBuilder out = new StringBuilder();
        encodeInto(out);
        return out.toString();
    }

    private void encodeInto(StringBuilder out) {
        switch (this) {
            case Str s -> {
                out.append('"');
                escape(s.value(), out);
                out.append('"');
            }
            case Num n -> {
                double d = n.value();
                if (d == Math.rint(d) && !Double.isInfinite(d) && Math.abs(d) < 1e15) {
                    out.append((long) d);
                } else {
                    out.append(d);
                }
            }
            case Bool b -> out.append(b.value());
            case Null ignored -> out.append("null");
            case Arr a -> {
                out.append('[');
                List<Json> items = a.items();
                for (int i = 0; i < items.size(); i++) {
                    if (i > 0) out.append(',');
                    items.get(i).encodeInto(out);
                }
                out.append(']');
            }
            case Obj o -> {
                out.append('{');
                boolean first = true;
                for (Map.Entry<String, Json> e : o.fields().entrySet()) {
                    if (!first) out.append(',');
                    first = false;
                    out.append('"');
                    escape(e.getKey(), out);
                    out.append('"').append(':');
                    e.getValue().encodeInto(out);
                }
                out.append('}');
            }
        }
    }

    private static void escape(String s, StringBuilder out) {
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"' -> out.append("\\\"");
                case '\\' -> out.append("\\\\");
                case '\n' -> out.append("\\n");
                case '\r' -> out.append("\\r");
                case '\t' -> out.append("\\t");
                default -> {
                    if (c < 0x20) {
                        out.append(String.format("\\u%04x", (int) c));
                    } else {
                        out.append(c);
                    }
                }
            }
        }
    }

    /**
     * Recursive-descent parser behind {@link Json#parse}. Strict RFC 8259 JSON:
     * every malformed input - including running off the end of the text mid-value -
     * surfaces as a {@link JsonException} with the offending position, never as a
     * raw {@code StringIndexOutOfBoundsException}/{@code NumberFormatException}.
     */
    final class Parser {
        private final String text;
        private final int maxDepth;
        private int pos;
        private int depth;

        Parser(String text, int maxDepth) {
            this.text = text;
            this.maxDepth = maxDepth;
        }

        boolean atEnd() {
            return pos >= text.length();
        }

        void skipWs() {
            while (pos < text.length()) {
                char c = text.charAt(pos);
                if (c != ' ' && c != '\t' && c != '\n' && c != '\r') {
                    break;
                }
                pos++;
            }
        }

        /** The char at {@link #pos}, or a JsonException if the input ended early. */
        private char peek() {
            if (atEnd()) {
                throw new JsonException("Unexpected end of JSON at " + pos);
            }
            return text.charAt(pos);
        }

        Json parseValue() {
            skipWs();
            char c = peek();
            return switch (c) {
                case '"' -> parseString();
                case '{' -> parseObject();
                case '[' -> parseArray();
                case 't' -> {
                    expect("true");
                    yield new Bool(true);
                }
                case 'f' -> {
                    expect("false");
                    yield new Bool(false);
                }
                case 'n' -> {
                    expect("null");
                    yield NULL;
                }
                default -> {
                    if (c == '-' || isDigit(c)) {
                        yield parseNumber();
                    }
                    throw new JsonException("Unexpected character '" + c + "' at " + pos);
                }
            };
        }

        private void expect(String literal) {
            if (!text.startsWith(literal, pos)) {
                throw new JsonException("Expected " + literal + " at " + pos);
            }
            pos += literal.length();
        }

        /** Called on every '[' / '{' - see {@link Json#DEFAULT_MAX_DEPTH} for why there's a cap. */
        private void enterNested() {
            if (++depth > maxDepth) {
                throw new JsonException("JSON nested deeper than the limit of " + maxDepth + " at " + pos);
            }
        }

        private Str parseString() {
            if (peek() != '"') {
                throw new JsonException("Expected a string at " + pos);
            }
            int start = pos;
            pos++; // opening quote
            StringBuilder sb = new StringBuilder();
            while (true) {
                if (atEnd()) {
                    throw new JsonException("Unterminated string starting at " + start);
                }
                char c = text.charAt(pos);
                if (c == '"') {
                    break;
                }
                if (c < 0x20) {
                    throw new JsonException("Unescaped control character in string at " + pos);
                }
                if (c == '\\') {
                    pos++;
                    if (atEnd()) {
                        throw new JsonException("Unterminated string starting at " + start);
                    }
                    char esc = text.charAt(pos);
                    switch (esc) {
                        case 'n' -> sb.append('\n');
                        case 'r' -> sb.append('\r');
                        case 't' -> sb.append('\t');
                        case 'b' -> sb.append('\b');
                        case 'f' -> sb.append('\f');
                        case '"' -> sb.append('"');
                        case '\\' -> sb.append('\\');
                        case '/' -> sb.append('/');
                        case 'u' -> {
                            sb.append(readUnicodeEscape());
                            pos += 4;
                        }
                        default -> throw new JsonException("Invalid escape \\" + esc + " at " + (pos - 1));
                    }
                } else {
                    sb.append(c);
                }
                pos++;
            }
            pos++; // closing quote
            return new Str(sb.toString());
        }

        /** Decodes the 4 hex digits of a unicode escape (pos is on its 'u'); doesn't advance pos. */
        private char readUnicodeEscape() {
            if (pos + 4 >= text.length()) {
                throw new JsonException("Truncated \\u escape at " + (pos - 1));
            }
            int value = 0;
            for (int i = 1; i <= 4; i++) {
                int digit = Character.digit(text.charAt(pos + i), 16);
                if (digit < 0) {
                    throw new JsonException("Invalid \\u escape at " + (pos - 1));
                }
                value = (value << 4) | digit;
            }
            return (char) value;
        }

        /** Strict JSON number grammar: {@code -?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?}. */
        private Num parseNumber() {
            int start = pos;
            if (peek() == '-') {
                pos++;
            }
            if (atEnd() || !isDigit(text.charAt(pos))) {
                throw new JsonException("Malformed number at " + start);
            }
            if (text.charAt(pos) == '0') {
                pos++;
            } else {
                skipDigits();
            }
            if (!atEnd() && text.charAt(pos) == '.') {
                pos++;
                if (atEnd() || !isDigit(text.charAt(pos))) {
                    throw new JsonException("Malformed number at " + start);
                }
                skipDigits();
            }
            if (!atEnd() && (text.charAt(pos) == 'e' || text.charAt(pos) == 'E')) {
                pos++;
                if (!atEnd() && (text.charAt(pos) == '+' || text.charAt(pos) == '-')) {
                    pos++;
                }
                if (atEnd() || !isDigit(text.charAt(pos))) {
                    throw new JsonException("Malformed number at " + start);
                }
                skipDigits();
            }
            // The grammar check above guarantees parseDouble accepts this substring.
            return new Num(Double.parseDouble(text.substring(start, pos)));
        }

        private static boolean isDigit(char c) {
            return c >= '0' && c <= '9';
        }

        private void skipDigits() {
            while (!atEnd() && isDigit(text.charAt(pos))) {
                pos++;
            }
        }

        private Arr parseArray() {
            enterNested();
            pos++; // [
            List<Json> items = new ArrayList<>();
            skipWs();
            if (peek() == ']') {
                pos++;
                depth--;
                return new Arr(items);
            }
            while (true) {
                items.add(parseValue());
                skipWs();
                char c = peek();
                if (c == ',') {
                    pos++;
                    continue;
                }
                if (c == ']') {
                    pos++;
                    break;
                }
                throw new JsonException("Expected , or ] at " + pos);
            }
            depth--;
            return new Arr(items);
        }

        private Obj parseObject() {
            enterNested();
            pos++; // {
            Map<String, Json> fields = new LinkedHashMap<>();
            skipWs();
            if (peek() == '}') {
                pos++;
                depth--;
                return new Obj(fields);
            }
            while (true) {
                skipWs();
                Str key = parseString();
                skipWs();
                if (peek() != ':') {
                    throw new JsonException("Expected : at " + pos);
                }
                pos++;
                Json value = parseValue();
                fields.put(key.value(), value);
                skipWs();
                char c = peek();
                if (c == ',') {
                    pos++;
                    continue;
                }
                if (c == '}') {
                    pos++;
                    break;
                }
                throw new JsonException("Expected , or } at " + pos);
            }
            depth--;
            return new Obj(fields);
        }
    }
}
